import { setLogLevel } from './adapter.js';
import * as commonDb from './adapter.js';
import { parser as timeline } from './adapter.js';
import * as timelineDB from './adapter.js';

describe('when parsing a timeline ', function () {
  beforeEach(function () {
    timeline.yy = timelineDB;
    timelineDB.clear();
    setLogLevel('trace');
  });
  describe('Timeline', function () {
    it('should default to LR direction when none is provided', function () {
      let str = `timeline
    section abc-123`;

      timeline.parse(str);
      expect(timelineDB.getDirection()).toBe('LR');
    });

    it('should parse TD direction', function () {
      let str = `timeline TD
    section abc-123`;

      timeline.parse(str);
      expect(timelineDB.getDirection()).toBe('TD');
    });

    it('should parse LR direction', function () {
      let str = `timeline LR
    section abc-123`;

      timeline.parse(str);
      expect(timelineDB.getDirection()).toBe('LR');
    });

    it('should handle a simple section definition abc-123', function () {
      let str = `timeline
    section abc-123`;

      timeline.parse(str);
      expect(timelineDB.getSections()).toEqual(['abc-123']);
    });

    it('should handle a simple section and only two tasks', function () {
      let str = `timeline
    section abc-123
    task1
    task2`;
      timeline.parse(str);
      timelineDB.getTasks().forEach((task) => {
        expect(task.section).toBe('abc-123');
        expect(['task1', 'task2']).toContain(task.task);
      });
    });

    it('should handle a two section and two corresponding tasks', function () {
      let str = `timeline
    section abc-123
    task1
    task2
    section abc-456
    task3
    task4`;
      timeline.parse(str);
      expect(timelineDB.getSections()).toEqual(['abc-123', 'abc-456']);
      timelineDB.getTasks().forEach((task) => {
        expect(['abc-123', 'abc-456']).toContain(task.section);
        expect(['task1', 'task2', 'task3', 'task4']).toContain(task.task);
        if (task.section === 'abc-123') {
          expect(['task1', 'task2']).toContain(task.task);
        } else {
          expect(['task3', 'task4']).toContain(task.task);
        }
      });
    });

    it('should handle a section, and task and its events', function () {
      let str = `timeline
    section abc-123
      task1: event1
      task2: event2: event3
   `;
      timeline.parse(str);
      expect(timelineDB.getSections()[0]).toBe('abc-123');
      timelineDB.getTasks().forEach((t) => {
        switch (t.task.trim()) {
          case 'task1':
            expect(t.events).toEqual(['event1']);
            break;

          case 'task2':
            expect(t.events).toEqual(['event2', 'event3']);
            break;

          default:
            break;
        }
      });
    });

    it('should handle a section, and task and its events including markdown link', function () {
      let str = `timeline
    section abc-123
      task1: [event1](http://example.com)
      task2: event2: event3
   `;
      timeline.parse(str);
      expect(timelineDB.getSections()[0]).toBe('abc-123');
      timelineDB.getTasks().forEach((t) => {
        switch (t.task.trim()) {
          case 'task1':
            expect(t.events).toEqual(['[event1](http://example.com)']);
            break;

          case 'task2':
            expect(t.events).toEqual(['event2', 'event3']);
            break;

          default:
            break;
        }
      });
    });

    it('should handle a section, and task and its multi line events', function () {
      let str = `timeline
    section abc-123
      task1: event1
      task2: event2: event3
           : event4: event5
   `;
      timeline.parse(str);
      expect(timelineDB.getSections()[0]).toBe('abc-123');
      timelineDB.getTasks().forEach((t) => {
        switch (t.task.trim()) {
          case 'task1':
            expect(t.events).toEqual(['event1']);
            break;

          case 'task2':
            expect(t.events).toEqual(['event2', 'event3', 'event4', 'event5']);
            break;

          default:
            break;
        }
      });
    });

    it('should handle a title, section, task, and events with semicolons', function () {
      let str = `timeline
      title ;my;title;
      section ;a;bc-123;
      ;ta;sk1;: ;ev;ent1; : ;ev;ent2; : ;ev;ent3;
   `;
      timeline.parse(str);
      expect(commonDb.getDiagramTitle()).toBe(';my;title;');
      expect(timelineDB.getSections()).toEqual([';a;bc-123;']);
      expect(timelineDB.getTasks()[0].events).toMatchInlineSnapshot(`
        [
          ";ev;ent1; ",
          ";ev;ent2; ",
          ";ev;ent3;",
        ]
      `);
    });

    it('should handle a title, section, task, and events with hashtags', function () {
      let str = `timeline
      title #my#title#
      section #a#bc-123#
      task1: #ev#ent1# : #ev#ent2# : #ev#ent3#
   `;
      timeline.parse(str);
      expect(commonDb.getDiagramTitle()).toBe('#my#title#');
      expect(timelineDB.getSections()).toEqual(['#a#bc-123#']);
      expect(timelineDB.getTasks()[0].task).toBe('task1');
      expect(timelineDB.getTasks()[0].events).toMatchInlineSnapshot(`
        [
          "#ev#ent1# ",
          "#ev#ent2# ",
          "#ev#ent3#",
        ]
      `);
    });
  });
});
